contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, bytes32 assertionId, bool assertedTruthfully) public payable {
        require(true);

        address expected = address(c.optimisticAsserter());
        require(caller != expected, "precondition: caller differs from optimisticAsserter");

        bool reverted;
        try c.assertionResolvedCallback(assertionId, assertedTruthfully) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted);
    }

    receive() external payable {}
}

contract InvMutTest {
