    }

    function run(address caller, bytes32 assertionId, bool assertedTruthfully) public payable {
        require(true);

        address expected = address(c.optimisticAsserter());

        bool reverted;
        if (caller == expected) {
            try c.assertionResolvedCallback(assertionId, assertedTruthfully) {
                reverted = false;
