contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 assertionId, bool assertedTruthfully, address caller) public {
        require(caller != address(this), "caller must not be this contract");
        require(caller != address(c.optimisticAsserter()), "caller must not be the optimistic asserter");

        bool revertedExternal;
        (bool okExternal, ) = address(c).call(abi.encodeWithSelector(C.assertionResolvedCallback.selector, assertionId, assertedTruthfully));
        revertedExternal = !okExternal;

        bool revertedAsserter;
        (bool okAsserter, ) = address(c).call(abi.encodeWithSelector(C.assertionResolvedCallback.selector, assertionId, assertedTruthfully));
        revertedAsserter = !okAsserter;

        assert(revertedExternal && !revertedAsserter);
    }
}

