contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 assertionId, address caller) public {
        // Read the immutable optimisticAsserter address through the public getter.
        address oa = address(c.optimisticAsserter());

        bool reverted;
        if (caller == oa) {
            // If caller is the optimistic asserter, the call should succeed.
            try c.assertionDisputedCallback(assertionId) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(!reverted);
        } else {
            // For any other caller, the call must revert.
            try c.assertionDisputedCallback(assertionId) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted);
        }
    }

    receive() external payable {}
}

