contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 identifier, uint256 time, bytes memory ancillaryData) public payable {
        require(true);

        bool reverted;
        try c.requestPrice(identifier, time, ancillaryData) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // c's optimisticAsserter is public immutable and is not visible via a getter, so we
        // cannot read it directly; but we can observe the intended invariant via the revert
        // behavior: the function must succeed only when caller is the optimisticAsserter.
        // Since this test contract is the caller and is not necessarily the optimisticAsserter,
        // we can only assert that when it does NOT revert, the event with matching args was emitted.
        // Event observation is not directly available; however, the public state and revert
        // surface tells us: when caller is optimisticAsserter, it must not revert; otherwise must revert.
        // We can check the latter for the current caller: the test contract is not the optimisticAsserter
        // (it was deployed by the checker, not by c), so a non-revert is impossible.
        // But the checker may call run with this contract as caller, and c was deployed by this
        // contract, so this contract is NOT the optimisticAsserter. Therefore requestPrice must revert.
        assert(reverted);
    }

    receive() external payable {}
}

